-- Model: sat_ssc_recordtype_curr
-- Description: Current active record for SAT_SSC_RECORDTYPE using ROW_NUMBER()
-- Generated by: bv pipeline generate transform with custom template
-- Satellite Type: SAT_ON_HUB
-- Parent: hub HUB_RECORDTYPE

WITH RANKED_RECORDS AS (
SELECT
    RECORDTYPE_HKEY,  -- hash key
    _AIRBYTE_EXTRACTED_AT AS _CURRENT_ACTIVE_TIMESTAMP, -- used: _AIRBYTE_EXTRACTED_AT
    -- Satellite Attributes
    _AIRBYTE_EXTRACTED_AT ,  -- is_trans_indicator
    ID                    ,  -- is_business_key
    LOAD_DATE             ,  -- is_load_timestamp
    LOAD_CYCLE_ID         ,  -- is_load_cycle_id
    DELETE_FLAG           ,  -- is_delete_flag
    BUSINESSPROCESSID     ,  -- is_other_attr
    CREATEDBYID           ,  -- is_other_attr
    CREATEDDATE           ,  -- is_other_attr
    DESCRIPTION           ,  -- is_other_attr
    DEVELOPERNAME         ,  -- is_other_attr
    ISACTIVE              ,  -- is_other_attr
    LASTMODIFIEDBYID      ,  -- is_other_attr
    LASTMODIFIEDDATE      ,  -- is_other_attr
    NAME                  ,  -- is_other_attr
    NAMESPACEPREFIX       ,  -- is_other_attr
    SOBJECTTYPE           ,  -- is_other_attr
    SYSTEMMODSTAMP        ,  -- is_other_attr
    _AIRBYTE_GENERATION_ID,  -- is_other_attr
    _AIRBYTE_RAW_ID          -- is_other_attr
    ,
    ROW_NUMBER() OVER (
        PARTITION BY RECORDTYPE_HKEY
        ORDER BY _AIRBYTE_EXTRACTED_AT DESC
    ) AS row_num
FROM {{ source('eli_dv_rv', 'sat_ssc_recordtype') }}
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RECORDS
WHERE row_num = 1
AND DELETE_FLAG = 'N'
